1	import { BaseSyntheticEvent, useCallback, useMemo, useRef } from 'react';
2	import {
3	    FieldValues,
4	    SubmitHandler,
5	    useForm,
6	    UseFormProps,
7	} from 'react-hook-form';
8	
9	import { RaRecord } from '../types';
10	import { SaveHandler, useSaveContext } from '../controller';
11	import { useRecordContext } from '../controller';
12	import getFormInitialValues from './getFormInitialValues';
13	import {
14	    getSimpleValidationResolver,
15	    ValidateForm,
16	} from './validation/getSimpleValidationResolver';
17	import { setSubmissionErrors } from './validation/setSubmissionErrors';
18	import { useNotifyIsFormInvalid } from './validation/useNotifyIsFormInvalid';
19	import { sanitizeEmptyValues as sanitizeValues } from './sanitizeEmptyValues';
20	
21	/**
22	 * Wrapper around react-hook-form's useForm
23	 *
24	 * This hook adds the following features to react-hook-form's useForm:
25	 *
26	 * - form initialization based on RecordContext
27	 * - validation based on a validate function
28	 * - sanitization of empty values
29	 * - notification on invalid form
30	 * - stop form submission event propagation
31	 */
32	export const useAugmentedForm = <RecordType = any>(
33	    props: UseAugmentedFormProps<RecordType>
34	) => {
35	    const {
36	        criteriaMode = 'firstError',
37	        defaultValues,
38	        formRootPathname,
39	        resolver,
40	        reValidateMode = 'onChange',
41	        onSubmit,
42	        sanitizeEmptyValues,
43	        validate,
44	        disableInvalidFormNotification,
45	        ...rest
46	    } = props;
47	    const record = useRecordContext(props);
48	    const saveContext = useSaveContext();
49	
50	    const defaultValuesIncludingRecord = useMemo(
51	        () => getFormInitialValues(defaultValues, record),
52	        // eslint-disable-next-line
53	        [
54	            // eslint-disable-next-line
55	            JSON.stringify({
56	                defaultValues:
57	                    typeof defaultValues === 'function'
58	                        ? 'function'
59	                        : defaultValues,
60	                record,
61	            }),
62	        ]
63	    );
64	
65	    const finalResolver = resolver
66	        ? resolver
67	        : validate
68	          ? getSimpleValidationResolver(validate)
69	          : undefined;
70	
71	    const form = useForm({
72	        criteriaMode,
73	        values: defaultValuesIncludingRecord,
74	        reValidateMode,
75	        resolver: finalResolver,
76	        ...rest,
77	    });
78	
79	    const formRef = useRef(form);
80	
81	    // notify on invalid form
82	    useNotifyIsFormInvalid(form.control, !disableInvalidFormNotification);
83	
84	    // submit callbacks
85	    const handleSubmit = useCallback(
86	        async (values, event) => {
87	            let errors;
88	            const finalValues = sanitizeEmptyValues
89	                ? sanitizeValues(values, record)
90	                : values;
91	            if (onSubmit) {
92	                errors = await onSubmit(finalValues, event);
93	            }
94	            if (onSubmit == null && saveContext?.save) {
95	                errors = await saveContext.save(finalValues, event);
96	            }
97	            if (errors != null) {
98	                setSubmissionErrors(errors, formRef.current.setError);
99	            }
100	        },
101	        [onSubmit, saveContext, sanitizeEmptyValues, record]
102	    );
103	
104	    const formHandleSubmit = useCallback(
105	        (event: BaseSyntheticEvent) => {
106	            if (!event.defaultPrevented) {
107	                // Prevent outer forms to receive the event
108	                event.stopPropagation();
109	                form.handleSubmit(handleSubmit)(event);
110	            }
111	            return;
112	        },
113	        [form, handleSubmit]
114	    );
115	
116	    return {
117	        form,
118	        handleSubmit,
119	        formHandleSubmit,
120	    };
121	};
122	
123	export type UseAugmentedFormProps<RecordType = any> =
124	    UseFormOwnProps<RecordType> &
125	        Omit<UseFormProps, 'onSubmit'> & {
126	            validate?: ValidateForm;
127	        };
128	
129	export interface UseFormOwnProps<RecordType = any> {
130	    defaultValues?: any;
131	    formRootPathname?: string;
132	    record?: Partial<RaRecord>;
133	    onSubmit?: SubmitHandler<FieldValues> | SaveHandler<RecordType>;
134	    sanitizeEmptyValues?: boolean;
135	    disableInvalidFormNotification?: boolean;
136	}
