242	/**
243	 * Get the initial record from the location, whether it comes from the location
244	 * state or is serialized in the url search part.
245	 */
246	export const getRecordFromLocation = ({ state, search }: Location) => {
247	    if (state && (state as StateWithRecord).record) {
248	        return (state as StateWithRecord).record;
249	    }
250	    if (search) {
251	        try {
252	            const searchParams = parse(search);
253	            if (searchParams.source) {
254	                if (Array.isArray(searchParams.source)) {
255	                    console.error(
256	                        `Failed to parse location search parameter '${search}'. To pre-fill some fields in the Create form, pass a stringified source parameter (e.g. '?source={"title":"foo"}')`
257	                    );
258	                    return;
259	                }
260	                return JSON.parse(searchParams.source);
261	            }
262	        } catch (e) {
263	            console.error(
264	                `Failed to parse location search parameter '${search}'. To pre-fill some fields in the Create form, pass a stringified source parameter (e.g. '?source={"title":"foo"}')`
265	            );
266	        }
267	    }
268	    return null;
269	};
270	
