n            let temporaryLink =\n                typeof rowClick === 'function'\n                    ? rowClick(record.id, resource, record)\n                    : rowClick;\n\n            const link = isPromise(temporaryLink)\n                ? await temporaryLink\n                : temporaryLink;\n\n            if (link === 'expand') {\n                handleToggleExpand(event);\n                return;\n            }\n            if (link === 'toggleSelection') {\n                handleToggleSelection(event);\n                return;\n            }\n            const path = await getPathForRecord({\n                record,\n                resource,\n                link,\n            });\n            if (path === false || path == null) {\n                return;\n            }\n            navigate(path, {\n                state: { _scrollToTop: true },\n            });\n        },\n        [\n            record,\n            resource,\n            rowClick,\n            navigate,\n            handleToggleExpand,\n            handleToggleSelection,\n            getPathForRecord,\n        ]\n    );\n\n    return (\n        <>\n            <TableRow\n                ref={ref}\n                className={clsx(className, {\n                    [DatagridClasses.expandable]: expandable,\n                    [DatagridClasses.selectable]: selectable,\n                    [DatagridClasses.clickableRow]: rowClick ?? hasDetailView,\n                })}\n                key={id}\n                style={style}\n                hover={hover}\n                onClick={handleClick}\n                {...rest}\n            >\n                {expand && (\n                    <TableCell\n                        padding=\"none\"\n                        className={DatagridClasses.expandIconCell}\n                    >\n                        {expandable && (\n                            <ExpandRowButton\n                                className={clsx(DatagridClasses.expandIcon, 