rPage?: number;\n    sort?: SortPayload;\n    resource?: string;\n    filterCallback?: (record: RecordType) => boolean;\n}\n\nexport type UseListValue<RecordType extends RaRecord = any> =\n    ListControllerResult<RecordType>;\n\nconst defaultFilter = {};\n"],"version":3}
