AAEF,uBAAe,CAAC,IAAI,GAAG;IACnB,GAAG,EAAE,YAAY;IACjB,aAAa,EAAE,MAAM;CACxB,CAAC;AACF,uBAAe,CAAC,QAAQ,GAAG;IACvB,GAAG,EAAE;QACD,OAAO,EAAE;YACL,YAAY;YACZ,8BAA8B;YAC9B,+BAA+B;SAClC;QACD,OAAO,EAAE;YACL,UAAU,EAAE,eAAe;YAC3B,8BAA8B,EAAE;gBAC5B,QAAQ,EAAE,eAAe;gBACzB,KAAK,EAAE,EAAE,MAAM,EAAE,EAAE,IAAI,EAAE,YAAY,EAAE,EAAE;aAC5C;YACD,+BAA+B,EAAE,+BAAwB,kBAAkB,CACvE,IAAI,CAAC,SAAS,CAAC,EAAE,IAAI,EAAE,aAAa,EAAE,CAAC,CAC1C,CAAE;SACN;QACD,OAAO,EAAE,EAAE,IAAI,EAAE,QAAQ,EAAE;KAC9B;IACD,aAAa,EAAE;QACX,OAAO,EAAE,CAAC,MAAM,EAAE,UAAU,CAAC;QAC7B,OAAO,EAAE;YACL,IAAI,EAAE,SAAS;YACf,QAAQ,EAAE;gBACN,QAAQ,EAAE,kBAAkB;aAC/B;SACJ;QACD,OAAO,EAAE,EAAE,IAAI,EAAE,QAAQ,EAAE;KAC9B;IACD,aAAa,EAAE;QACX,OAAO,EAAE,CAAC,MAAM,EAAE,UAAU,CAAC;QAC7B,OAAO,EAAE;YACL,IAAI,EAAE,SAAS;YACf,QAAQ,EAAE,EAAE,KAAK,EAAE,OAAO,EAAE,IAAI,EAAE,YAAY,EAAE;SACnD;QACD,OAAO,EAAE,EAAE,IAAI,EAAE,QAAQ,EAAE;KAC9B;CACJ,CAAC","names":[],"sources":["/workspace/repo/packages/ra-core/src/form/Form.stories.tsx"],"sourcesContent":["import * as React from 'react';\nimport {\n    useController,\n    UseControllerProps,\n    useFormState,\n} from 'react-hook-form';\nimport { zodResolver } from '@hookform/resolvers/zod';\nimport * as z from 'zod';\nimport polyglotI18nProvider from 'ra-i18n-polyglot';\nimport englishMessages from 'ra-language-english';\nimport {\n    Route,\n    Routes,\n    useNavigate,\n    Link,\n    HashRouter,\n    useLocation,\n} from 'react-router-dom';\n\nimport { CoreAdminContext } from '../core';\nimport { RecordContextProvider } from '../controller';\nimport { TestMemoryRouter } from '../routing';\nimport { Form, FormProps } from './Form';\nimport { useInput } from './useInput';\nimport { required, ValidationError } from './validation';\nimport { mergeTranslations } from '../i18n';\nimport { I18nProvider, RaRecord } from '../types';\nimport { SaveContextProvider, useNotificationContext } from '..';\n\nexport default {\n    title: 'ra-core/form/Form',\n};\n\nconst Input = props => {\n    const { field, fieldState } = useInput(props);\n    return (\n        <div\n            style={{\n                display: 'flex',\n                gap: '1em',\n                margin: '1em',\n                alignItems: 'center',\n            }}\n        >\n            <label htmlFor={field.name}>{field.name}</label>\n            <input\n                aria-label={field.name}\n                id={field.name}\n                type=\"text\"\n                aria-invalid={fieldState.invalid}\n                {...field}\n            />\n            {fieldState.error && fieldState.error.message ? (\n                <ValidationError error={fieldState.error.message} />\n            ) : null}\n        </div>\n    );\n};\n\nconst SubmitButton = () => {\n    const state = useFormState();\n\n    return (\n        <button type=\"submit\" disabled={!state.isDirty}>\n            Submit\n        </button>\n    );\n};\n\nexport const Basic = () => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    return (\n        <CoreAdminContext>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{ id: 1, field1: 'bar', field6: null }}\n            >\n                <Input source=\"field1\" />\n                <Input source=\"field2\" defaultValue=\"bar\" />\n                <Input source=\"field3\" defaultValue=\"\" />\n                <Input source=\"field4\" />\n                <Input source=\"field5\" parse={v => v || undefined} />\n                <Input source=\"field6\" />\n                <SubmitButton />\n            </Form>\n            <pre>{JSON.stringify(submittedData, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nconst CustomInput = (props: UseControllerProps) => {\n    const { field, fieldState } = useController(props);\n    return (\n        <div\n            style={{\n                display: 'flex',\n                gap: '1em',\n                margin: '1em',\n                alignItems: 'center',\n            }}\n        >\n            <label htmlFor={field.name}>{field.name}</label>\n            <input\n                aria-label={field.name}\n                id={field.name}\n                type=\"text\"\n                aria-invalid={fieldState.invalid}\n                {...field}\n                value={field.value ?? ''}\n            />\n            <p>{fieldState.error?.message}</p>\n        </div>\n    );\n};\n\nexport const SanitizeEmptyValues = () => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    const field11 = { name: 'field11' };\n    const field12 = {\n        name: 'field12',\n        defaultValue: 'bar',\n    };\n    const field13 = {\n        name: 'field13',\n        defaultValue: '',\n    };\n    const field14 = { name: 'field14' };\n    const field16 = { name: 'field16' };\n    return (\n        <CoreAdminContext>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{\n                    id: 1,\n                    field1: 'bar',\n                    field6: null,\n                    field11: 'bar',\n                    field16: null,\n                }}\n                sanitizeEmptyValues\n            >\n                <Input source=\"field1\" />\n                <Input source=\"field2\" defaultValue=\"bar\" />\n                <Input source=\"field3\" defaultValue=\"\" />\n                <Input source=\"field4\" />\n                <Input source=\"field5\" parse={v => v || undefined} />\n                <Input source=\"field6\" />\n                <CustomInput {...field11} />\n                <CustomInput {...field12} />\n                <CustomInput {...field13} />\n                <CustomInput {...field14} />\n                <CustomInput {...field16} />\n\n                <SubmitButton />\n            </Form>\n            <pre data-testid=\"result\">\n                {JSON.stringify(submittedData, null, 2)}\n            </pre>\n        </CoreAdminContext>\n    );\n};\n\nexport const NullValue = () => {\n    const [result, setResult] = React.useState<any>();\n    return (\n        <CoreAdminContext>\n            <Form record={{ foo: null }} onSubmit={data => setResult(data)}>\n                <Input source=\"foo\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(result, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nexport const UndefinedValue = () => {\n    const [result, setResult] = React.useState<any>();\n    return (\n        <CoreAdminContext>\n            <Form record={{}} onSubmit={data => setResult(data)}>\n                <Input source=\"foo\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(result, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nconst defaultI18nProvider = polyglotI18nProvider(() =>\n    mergeTranslations(englishMessages, {\n        app: {\n            validation: {\n                required: 'This field must be provided',\n            },\n        },\n    })\n);\n\nexport const FormLevelValidation = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    return (\n        <CoreAdminContext i18nProvider={i18nProvider}>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{ id: 1, field1: 'bar', field6: null }}\n                validate={(values: any) => {\n                    const errors: any = {};\n                    if (!values.defaultMessage) {\n                        errors.defaultMessage = 'ra.validation.required';\n                    }\n                    if (!values.customMessage) {\n                        errors.customMessage = 'This field is required';\n                    }\n                    if (!values.customMessageTranslationKey) {\n                        errors.customMessageTranslationKey =\n                            'app.validation.required';\n                    }\n                    if (!values.missingCustomMessageTranslationKey) {\n                        errors.missingCustomMessageTranslationKey =\n                            'app.validation.missing';\n                    }\n                    return errors;\n                }}\n            >\n                <Input source=\"defaultMessage\" />\n                <Input source=\"customMessage\" />\n                <Input source=\"customMessageTranslationKey\" />\n                <Input source=\"missingCustomMessageTranslationKey\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(submittedData, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nexport const InputLevelValidation = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    return (\n        <CoreAdminContext i18nProvider={i18nProvider}>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{ id: 1, field1: 'bar', field6: null }}\n            >\n                <Input source=\"defaultMessage\" validate={required()} />\n                <Input\n                    source=\"customMessage\"\n                    validate={required('This field is required')}\n                />\n                <Input\n                    source=\"customMessageTranslationKey\"\n                    validate={required('app.validation.required')}\n                />\n                <Input\n                    source=\"missingCustomMessageTranslationKey\"\n                    validate={required('app.validation.missing')}\n                />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(submittedData, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nconst zodSchema = z.object({\n    defaultMessage: z.string(), //.min(1),\n    customMessage: z.string({\n        required_error: 'This field is required',\n    }),\n    customMessageTranslationKey: z.string({\n        required_error: 'app.validation.required',\n    }),\n    missingCustomMessageTranslationKey: z.string({\n        required_error: 'app.validation.missing',\n    }),\n});\n\nexport const ZodResolver = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => {\n    const [result, setResult] = React.useState<any>();\n    return (\n        <CoreAdminContext i18nProvider={i18nProvider}>\n            <Form\n                record={{}}\n                onSubmit={data => setResult(data)}\n                resolver={zodResolver(zodSchema)}\n            >\n                <Input source=\"defaultMessage\" />\n                <Input source=\"customMessage\" />\n                <Input source=\"customMessageTranslationKey\" />\n                <Input source=\"missingCustomMessageTranslationKey\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(result, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nconst FormUnderTest = () => {\n    const navigate = useNavigate();\n    return (\n        <>\n            <Form\n                record={{ title: 'lorem', body: 'ipsum' }}\n                onSubmit={() => setTimeout(() => navigate('/'), 0)}\n                warnWhenUnsavedChanges\n            >\n                <Input source=\"title\" />\n                <Input source=\"body\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <Link to=\"/\">Leave the form</Link>\n        </>\n    );\n};\n\nexport const WarnWhenUnsavedChanges = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => (\n    <CoreAdminContext i18nProvider={i18nProvider}>\n        <Routes>\n            <Route path=\"/\" element={<Link to=\"/form\">Go to form</Link>} />\n            <Route path=\"/form\" element={<FormUnderTest />} />\n        </Routes>\n    </CoreAdminContext>\n);\n\nexport const InNonDataRouter = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => (\n    <HashRouter>\n        <CoreAdminContext i18nProvider={i18nProvider}>\n            <Routes>\n                <Route path=\"/\" element={<Link to=\"/form\">Go to form</Link>} />\n                <Route path=\"/form\" element={<FormUnderTest />} />\n            </Routes>\n        </CoreAdminContext>\n    </HashRouter>\n);\n\nconst Notifications = () => {\n    const { notifications } = useNotificationContext();\n    return (\n        <ul>\n            {notifications.map(({ message }, id) => (\n                <li key={id}>{message}</li>\n            ))}\n        </ul>\n    );\n};\n\nexport const ServerSideValidation = () => {\n    const save = React.useCallback(values => {\n        const errors: any = {};\n        if (!values.defaultMessage) {\n            errors.defaultMessage = 'ra.validation.required';\n        }\n        if (!values.customMessage) {\n            errors.customMessage = 'This field is required';\n        }\n        if (!values.customMessageTranslationKey) {\n            errors.customMessageTranslationKey = 'app.validation.required';\n        }\n        if (!values.missingCustomMessageTranslationKey) {\n            errors.missingCustomMessageTranslationKey =\n                'app.validation.missing';\n        }\n        if (!values.customGlobalMessage) {\n            errors.customGlobalMessage = 'ra.validation.required';\n            errors.root = {\n                serverError: 'There are validation errors. Please fix them.',\n            };\n        }\n        return Object.keys(errors).length > 0 ? errors : undefined;\n    }, []);\n    return (\n        <CoreAdminContext i18nProvider={defaultI18nProvider}>\n            <SaveContextProvider value={{ save }}>\n                <Form\n                    record={{\n                        id: 1,\n                        defaultMessage: 'foo',\n                        customMessage: 'foo',\n                        customMessageTranslationKey: 'foo',\n                        missingCustomMessageTranslationKey: 'foo',\n                        customGlobalMessage: 'foo',\n                    }}\n                >\n                    <Input source=\"defaultMessage\" />\n                    <Input source=\"customMessage\" />\n                    <Input source=\"customMessageTranslationKey\" />\n                    <Input source=\"missingCustomMessageTranslationKey\" />\n                    <Input source=\"customGlobalMessage\" />\n                    <button type=\"submit\">Submit</button>\n                </Form>\n                <Notifications />\n            </SaveContextProvider>\n        </CoreAdminContext>\n    );\n};\n\nconst Tab = ({\n    children,\n    name,\n}: {\n    children: React.ReactNode;\n    name: string;\n}) => {\n    const location = useLocation();\n\n    return (\n        <div\n            style={{\n                display: location.pathname.endsWith(`/${name}`)\n                    ? 'flex'\n                    : 'none',\n                flexDirection: 'column',\n            }}\n        >\n            {children}\n        </div>\n    );\n};\n\nconst TabbedForm = () => {\n    const location = useLocation();\n\n    return (\n        <>\n            <div style={{ display: 'flex', gap: '1rem' }}>\n                <Link\n                    to={{\n                        ...location,\n                        pathname: 'general',\n                    }}\n                >\n                    General\n                </Link>\n                <Link\n                    to={{\n                        ...location,\n                        pathname: 'content',\n                    }}\n                >\n                    Settings\n                </Link>\n            </div>\n            <Tab name=\"general\">\n                <Input source=\"title\" />\n                <Input source=\"category\" />\n            </Tab>\n            <Tab name=\"content\">\n                <Input source=\"body\" />\n            </Tab>\n        </>\n    );\n};\n\nconst FormWithSubRoutes = (props: Partial<FormProps>) => {\n    return (\n        <Form {...props}>\n            <TabbedForm />\n            <SubmitButton />\n        </Form>\n    );\n};\n\nexport const MultiRoutesForm = ({\n    url,\n    initialRecord,\n    defaultValues,\n}: {\n    url?: any;\n    initialRecord?: Partial<RaRecord>;\n    defaultValues?: Partial<RaRecord>;\n}) => (\n    <React.StrictMode>\n        <TestMemoryRouter key={url} initialEntries={[url]}>\n            <CoreAdminContext i18nProvider={defaultI18nProvider}>\n                <Routes>\n                    <Route\n                        path=\"/form/*\"\n                        element={\n                            <RecordContextProvider value={initialRecord}>\n                                <FormWithSubRoutes\n                                    defaultValues={defaultValues}\n                                />\n                            </RecordContextProvider>\n                        }\n                    />\n                </Routes>\n            </CoreAdminContext>\n        </TestMemoryRouter>\n    </React.StrictMode>\n);\n\nMultiRoutesForm.args = {\n    url: 'unmodified',\n    initialRecord: 'none',\n};\nMultiRoutesForm.argTypes = {\n    url: {\n        options: [\n            'unmodified',\n            'modified with location state',\n            'modified with location search',\n        ],\n        mapping: {\n            unmodified: '/form/general',\n            'modified with location state': {\n                pathname: '/form/general',\n                state: { record: { body: 'from-state' } },\n            },\n            'modified with location search': `/form/general?source=${enco